window.REGISTER = {"categories": {"PLT": "Platform and tenancy", "DET": "Determinism and audit", "PPL": "People and lifecycle", "CON": "Consent and data protection", "WEB": "Website and CMS", "CAP": "Capture and forms", "MSG": "Messaging", "WFL": "Workflows and automation", "CMP": "Campaigns", "SOC": "Social engine", "BKG": "Booking and diary", "PAY": "Payments", "CLN": "Clinical (aesthetics pack)", "RPT": "Reporting and insight", "UXC": "Client console", "OPS": "Operator console and delivery", "AIA": "AI assistance", "INT": "Integrations and migration", "SEC": "Security and operations", "CMPL": "Vertical compliance", "COM": "Commercial model"}, "rows": [{"id": "PLT-001", "req": "Every record, file, job and query is scoped to one tenant. Isolation is enforced in the database (row-level security), not only in application code.", "why": "Multi-tenant platform holding health-adjacent data. App-layer filters regress quietly.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Partial", "trace": "booking-engine-plan.md §4, §11; data-protection-review-2026-08-18"}, {"id": "PLT-002", "req": "A tenant is defined entirely by configuration data: brand tokens, catalogue, hours, rule tables, templates, workflows, compliance rules. Onboarding a tenant in an existing vertical needs zero code.", "why": "The transferability claim only holds if a new tenant is data, not a fork.", "pri": "Must", "scope": "Core", "surface": "Operator", "status": "Partial", "trace": "Vera onboarded to Studio with zero code (24 Jul); content/config/ pattern"}, {"id": "PLT-003", "req": "Configuration is versioned. Every change records author, time and reason, and every operational record stores the config version it was created under.", "why": "Needed to replay or explain any past outcome.", "pri": "Must", "scope": "Core", "surface": "System", "status": "New", "trace": ""}, {"id": "PLT-004", "req": "Vertical packs layer on the core: schema extensions, catalogue fields, rule tables, templates, lint rules and optional modules. Core never imports pack code.", "why": "Keeps the platform niche-agnostic. Same boundary rule as the wealth-onboarding split.", "pri": "Must", "scope": "Core", "surface": "Operator", "status": "New", "trace": "SOP-WEALTH-006 (no cross-imports)"}, {"id": "PLT-005", "req": "Modules switch on per tenant (Site, Capture, Messaging, Workflows, Campaigns, Social, Booking, Payments, Clinical). The console shows only enabled modules.", "why": "Plans are sold by module; a salon does not see a clinical record.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "PLT-006", "req": "One operational runtime hosts the spine and operational modules (Node/TypeScript + PostgreSQL). No per-feature backends.", "why": "Today one person can sit in four stores: consultation-api SQLite, proposed PHP/MySQL opt-in, booking Postgres, Faces.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Designed", "trace": "consultation-api/README.md; docs/email-sequence-design.md 'Reconcile before build'; D4 reopened 26 Sep 2026: Velocity DB has no PITR; split host proposed (platform-design.md §3.4)"}, {"id": "PLT-007", "req": "Two planes. Content plane (pages, blog, templates, social posts) is versioned in git and built statically. Operational plane (people, events, bookings, sends) lives in the database.", "why": "Git already gives the content side review, history and rollback. Operational data needs transactions.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Partial", "trace": "site/ Astro + Stage + Loop 2"}, {"id": "PLT-008", "req": "Tenant provisioning is a scripted, idempotent job: create tenant, seed pack defaults, site repo from template, Stage engagement, DNS and email checklist.", "why": "Repeatable onboarding is the product, not a consulting exercise.", "pri": "Should", "scope": "Core", "surface": "Operator", "status": "Partial", "trace": "/onboard-client skill; Studio onboarding"}, {"id": "PLT-009", "req": "All personal data and backups stay in a UK region.", "why": "UK GDPR posture and client expectation for clinic data.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Designed", "trace": "clinical plan §2.1; consultation-api README"}, {"id": "PLT-010", "req": "A tenant can export all its data (people, events, bookings, documents, content) in open formats at any time. This is also the exit path.", "why": "Escaping Faces lock-in is why PureMed is moving. The platform must not reproduce it.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": "buy-vs-build-spike-2026-08-15"}, {"id": "PLT-011", "req": "Tenant offboarding deletes data according to retention rules and logs what was kept and why.", "why": "Contract end must be clean and provable.", "pri": "Should", "scope": "Core", "surface": "Operator", "status": "New", "trace": ""}, {"id": "DET-001", "req": "Same config version plus same inputs produces the same journey, requirements, price, documents, sends and schedule, every time, and the system can prove it afterwards.", "why": "The platform's governing definition, inherited from the booking engine.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Designed", "trace": "booking-engine-plan.md §2"}, {"id": "DET-002", "req": "Every state change in every module is written to one append-only event log with actor (person, staff, job, workflow), time, cause and config version.", "why": "The determinism review failed the booking service for having no event log.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Partial", "trace": "determinism-review-2026-08-18"}, {"id": "DET-003", "req": "Current state can be rebuilt by replaying the event log, and a replay test runs in CI.", "why": "Proves DET-002 is complete, not decorative.", "pri": "Should", "scope": "Core", "surface": "System", "status": "New", "trace": ""}, {"id": "DET-004", "req": "Every automated action records the workflow, step and rule IDs that caused it, and the client can see this as a plain-language 'why this happened'.", "why": "Clients trust automation they can explain to a patient.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "DET-005", "req": "Snapshot, do not reference: bookings, sends and signed documents store the price, template version and rule IDs in force at commit.", "why": "Determinism review found no booking snapshot.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Partial", "trace": "booking-engine-plan.md §4; determinism-review-2026-08-18"}, {"id": "DET-006", "req": "No LLM in any decision path: eligibility, price, availability, whether or when to send, segment membership, whether to publish. AI drafts only, for human approval.", "why": "Non-determinism in a regulated path is a defect.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Designed", "trace": "booking-engine-plan.md §2 rule 4; content/PLAN.md principle 1"}, {"id": "DET-007", "req": "Rules are data (tables with IDs) evaluated by pure functions with no I/O. Each rule table has a ratified rule-trace contract checked by `make trace`.", "why": "Only booking-engine has a contract today.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Partial", "trace": "SOP-OPS-005; rule-trace.js"}, {"id": "DET-008", "req": "Scheduled work computes due times from stored inputs (enrolled_at, step offset, quiet hours, tenant timezone). Nothing depends on when a cron happens to wake.", "why": "Makes the send schedule predictable and testable.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Designed", "trace": "email-sequence-design.md worker rules"}, {"id": "DET-009", "req": "Every outbound side effect (send, publish, charge) carries an idempotency key. Overlapping workers cannot double-send.", "why": "Double sends to a patient are the most visible automation failure.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Designed", "trace": "email-sequence-design.md locking"}, {"id": "DET-010", "req": "Pure engines (availability, rules, segment evaluation, schedule computation) have property-based tests including DST boundaries.", "why": "A deterministic system is one whose determinism is demonstrated.", "pri": "Should", "scope": "Core", "surface": "System", "status": "Partial", "trace": "booking-engine service/test"}, {"id": "PPL-001", "req": "One Person record per human per tenant, shared by every module. Subscriber, lead, patient and customer are lifecycle stages of the same record.", "why": "The single most important fix to today's estate.", "pri": "Must", "scope": "Core", "surface": "System", "status": "New", "trace": "CRM-001; booking-engine 'client' entity (thin)"}, {"id": "PPL-002", "req": "Identity matching is deterministic on normalised email and phone. Ambiguous matches go to a review queue and are never auto-merged.", "why": "Wrong merges leak one person's history into another's.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "PPL-003", "req": "Staff can merge and unmerge people, with a full audit trail.", "why": "Duplicates will happen with walk-ins and phone bookings.", "pri": "Should", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "PPL-004", "req": "Lifecycle stage is derived by rules from events (Subscriber, Lead, Booked, Client, Lapsed, Unsubscribed), never set by hand.", "why": "Hand-set stages drift and make segments lie.", "pri": "Must", "scope": "Core", "surface": "System", "status": "New", "trace": ""}, {"id": "PPL-005", "req": "Derived fields computed from events: first seen, source, last booked, last attended, next booking, next recall due, total bookings, lifetime spend, last message, last reply.", "why": "Answers 'when did this client last book?' without a report.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "PPL-006", "req": "Person timeline: one chronological view of every event (opt-in, messages, clicks, bookings, attendance, payments, forms, workflow steps, staff notes), filterable by module.", "why": "The client's main working view of a relationship.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "PPL-007", "req": "Acquisition source captured at first touch (UTM, referrer, form, channel, which Instagram account) and carried onto every booking.", "why": "Without it 'drive bookings' cannot be measured.", "pri": "Must", "scope": "Core", "surface": "System", "status": "New", "trace": "CRM-003; growth plan open item"}, {"id": "PPL-008", "req": "Tags can be applied by rules or staff, and a tag being added can trigger a workflow.", "why": "The tag model from the email design, made platform-wide.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "Designed", "trace": "email-sequence-design.md §2"}, {"id": "PPL-009", "req": "Segments are saved rule queries over person fields and events. Membership is computed deterministically and its count is previewed before use.", "why": "Campaigns and workflows target segments, never hand-picked lists.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "PPL-010", "req": "Staff notes on a person (non-clinical), stored separately from clinical notes.", "why": "Reception needs a place to write that isn't the clinical record.", "pri": "Should", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "PPL-011", "req": "Search people by name, email, phone or tag.", "why": "Basic lookup from a phone between appointments.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "PPL-012", "req": "Import people from CSV or a legacy system with a mapping preview and dry run before commit.", "why": "Every tenant arrives with a list somewhere.", "pri": "Should", "scope": "Core", "surface": "Operator", "status": "New", "trace": "MIG rows"}, {"id": "CON-001", "req": "Consent ledger: each consent (marketing email, marketing WhatsApp/SMS, clinical photo, marketing photo, treatment) is its own row with status, wording version, time, source and withdrawal event.", "why": "Consent has a lifecycle, not a boolean.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Designed", "trace": "clinical plan §3.1; email design consent_version"}, {"id": "CON-002", "req": "Every marketing send checks consent at send time, not only at enrolment.", "why": "Withdrawal must take effect on the next step.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Designed", "trace": "email design worker rules"}, {"id": "CON-003", "req": "One-click unsubscribe (RFC 8058) plus a visible link. Withdrawal stops every marketing workflow immediately.", "why": "Legal requirement and Gmail/Yahoo bulk sender rules.", "pri": "Must", "scope": "Core", "surface": "Public", "status": "Designed", "trace": "email design §4"}, {"id": "CON-004", "req": "Lawful basis recorded per data category and purpose, per pack. The record of processing is generated by `make datamap`.", "why": "Generated, not hand-maintained.", "pri": "Must", "scope": "Core", "surface": "Operator", "status": "Partial", "trace": "SOP-OPS-006; data-map.js"}, {"id": "CON-005", "req": "Retention rules per data category, set per pack and tenant, enforced by a scheduled sweep that logs what it deleted.", "why": "consultation-api uses a 400-day placeholder.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Partial", "trace": "consultation-api purge.js"}, {"id": "CON-006", "req": "Subject access request: one action produces a complete export of one person across all modules.", "why": "Impossible today across four stores.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": "SEC-006; CRM-002"}, {"id": "CON-007", "req": "Erasure removes or anonymises identity and marketing data while keeping evidential records under a documented retention basis.", "why": "Separate tables with a linking key make this answerable.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "Designed", "trace": "booking-engine-plan.md §4, §10"}, {"id": "CON-008", "req": "Age gate (18+) where the pack requires it, recorded on the person.", "why": "Aesthetics advertising and treatment rules.", "pri": "Must", "scope": "Pack:Aesthetics", "surface": "Public", "status": "Designed", "trace": "ACCT-003"}, {"id": "CON-009", "req": "Special category (health) data stays in the clinical module. It never reaches marketing segments, message merge fields or analytics.", "why": "The boundary that lets growth tooling sit next to clinical records.", "pri": "Must", "scope": "Pack:Aesthetics", "surface": "System", "status": "New", "trace": ""}, {"id": "CON-010", "req": "A DPIA is completed per pack before any tenant in that pack goes live, with a tenant addendum per tenant.", "why": "Data protection review: no DPIA anywhere.", "pri": "Must", "scope": "Pack:Aesthetics", "surface": "Operator", "status": "New", "trace": "data-protection-review-2026-08-18"}, {"id": "CON-011", "req": "Sub-processor register per tenant (Google Workspace, Stripe, Meta, host) with DPAs on file.", "why": "Controller/processor clarity for every tenant.", "pri": "Must", "scope": "Core", "surface": "Operator", "status": "New", "trace": ""}, {"id": "CON-012", "req": "Health-adjacent form answers are collected only if a workflow actually uses them, and are flagged in the data map.", "why": "Data minimisation.", "pri": "Should", "scope": "Pack:Aesthetics", "surface": "System", "status": "Designed", "trace": "email design §5"}, {"id": "WEB-001", "req": "Tenant site is a static Astro build from a vertical template, deployed by CI. Build pass or fail is the gate.", "why": "Proven on MSS and PureMed.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Built", "trace": "site/; mss-astro-cloudways-setup.md"}, {"id": "WEB-002", "req": "Client edits copy and images in place on a preview of the real site, submits, and changes publish after the gate.", "why": "Live on Stage for PureMed.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "Built", "trace": "stage-client-autonomy-plan.md; SOP-PUREMED-001"}, {"id": "WEB-003", "req": "Client can add and remove repeatable items (treatments, FAQs, team).", "why": "Live, clone fixes 18 Sep.", "pri": "Should", "scope": "Core", "surface": "Client console", "status": "Built", "trace": "CLAUDE.md 18 Sep note"}, {"id": "WEB-004", "req": "Client can create and edit blog posts as content, not developer-held data.", "why": "Blog copy lives in blog-posts.js today and is not editable on Stage.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": "puremed CLAUDE.md 16 Sep note"}, {"id": "WEB-005", "req": "Client creates landing pages and microsites from templates with parameters (treatment, offer, lead magnet), each on its own URL.", "why": "Microsite builds are operator-only scripts today.", "pri": "Should", "scope": "Core", "surface": "Client console", "status": "Partial", "trace": "tools/build-microsites.py; SOP-PUREMED-002"}, {"id": "WEB-006", "req": "Every CTA resolves from the catalogue (for example a booking deep link with service ID). Unmapped or broken CTAs fail the build instead of falling back silently.", "why": "Treatment IDs are hand-mapped today; unmapped ones fall back to a generic link.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Partial", "trace": "puremed CLAUDE.md treatmentId notes"}, {"id": "WEB-007", "req": "SEO basics generated per pack: meta, Open Graph, sitemap, schema.org business type.", "why": "Consistent across tenants for free.", "pri": "Should", "scope": "Core", "surface": "System", "status": "Partial", "trace": ""}, {"id": "WEB-008", "req": "Preflight gate before publish: build, 390/768/1440 viewport pass, link check, placeholder scan.", "why": "Already the deploy gate.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Built", "trace": "make preflight; deploy-preflight agent"}, {"id": "WEB-009", "req": "Pack compliance lint runs on site copy (for example no prescription-only medicine names in promotional copy).", "why": "Lint exists for social only.", "pri": "Must", "scope": "Pack:Aesthetics", "surface": "System", "status": "Partial", "trace": "content-lint.js"}, {"id": "WEB-010", "req": "Page version history with one-step rollback.", "why": "Git holds it; the client can't reach it.", "pri": "Should", "scope": "Core", "surface": "Client console", "status": "Partial", "trace": ""}, {"id": "WEB-011", "req": "Forms and the booking widget are components the client can place on any page.", "why": "Capture and booking must not need a developer per page.", "pri": "Should", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "WEB-012", "req": "Public surfaces meet WCAG 2.2 AA.", "why": "Equality Act duty and conversion.", "pri": "Must", "scope": "Core", "surface": "Public", "status": "Partial", "trace": "clinical plan §2.8"}, {"id": "WEB-013", "req": "The production editing and CMS surface runs off the Pi, on a managed host with uptime and backups.", "why": "Stage runs on a Pi on home broadband. Acceptable for review, not for a paid product.", "pri": "Must", "scope": "Core", "surface": "System", "status": "New", "trace": "consultation-api README 'Not the Raspberry Pi'"}, {"id": "CAP-001", "req": "Form definitions are config: fields, validation, consent wording version, tags to apply, workflow to trigger, redirect.", "why": "New lead magnet = new config, no code.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "Designed", "trace": "email design sequence config"}, {"id": "CAP-002", "req": "One capture endpoint for every form, writing to the Person record. Replaces consultation-api and the proposed PHP opt-in endpoint.", "why": "Two lead backends for one site is the wrong end state.", "pri": "Must", "scope": "Core", "surface": "System", "status": "New", "trace": "email design 'Reconcile before build' item 1"}, {"id": "CAP-003", "req": "Spam defence by honeypot and rate limit; no CAPTCHA by default.", "why": "Friction costs leads.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Designed", "trace": "email design §3"}, {"id": "CAP-004", "req": "Lead magnets: asset at an unlisted URL, delivery message sent immediately, download recorded as an event.", "why": "guide-opt-in is the first one.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Designed", "trace": "web/guide-opt-in.html; email design"}, {"id": "CAP-005", "req": "Quiz and consultation journeys are decision tables mapping answers to a recommendation, and each recommendation maps to a catalogue item.", "why": "consultation.astro hardcodes this logic today.", "pri": "Should", "scope": "Core", "surface": "Public", "status": "Partial", "trace": "site/src/pages/consultation.astro"}, {"id": "CAP-006", "req": "Staff are notified of submissions according to tenant settings: email to the integration mailbox (care@ for PureMed) by default, plus optional phone push.", "why": "Leads must be followed up the same day, in the inbox the team already works from.", "pri": "Should", "scope": "Core", "surface": "Client console", "status": "Partial", "trace": "consultation-api ntfy"}, {"id": "CAP-007", "req": "Repeat submissions follow fixed rules: resend the asset, do not re-enrol within N days, never re-enrol an unsubscribed person.", "why": "Stops accidental re-sends.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Designed", "trace": "email design re-submission rules"}, {"id": "MSG-001", "req": "One message model across channels: email first, WhatsApp Business second, SMS optional.", "why": "Aftercare only lands on WhatsApp for PureMed.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Partial", "trace": "systems proposal item 6"}, {"id": "MSG-002", "req": "Message templates are versioned content (HTML, plain text, merge fields), approved before use. Each send records the template version.", "why": "Regulated copy must be approved in advance.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "Designed", "trace": "email design §5"}, {"id": "MSG-003", "req": "Merge fields come from a whitelist per pack. Clinical fields are never available to marketing templates.", "why": "Enforces CON-009 at the template layer.", "pri": "Must", "scope": "Core", "surface": "System", "status": "New", "trace": ""}, {"id": "MSG-004", "req": "Sending from the tenant's integration mailbox is blocked until an onboarding check confirms SPF, DKIM and DMARC on its domain (for PureMed, puremed.uk).", "why": "Without all three Gmail junks the mail.", "pri": "Must", "scope": "Core", "surface": "Operator", "status": "Designed", "trace": "email design §4"}, {"id": "MSG-005", "req": "The sending address is always the integration mailbox (care@puremed.uk). The display name may name the clinician (\"Nafisa at PureMed\"). Replies return to the same mailbox.", "why": "A named sender gets better engagement without inventing addresses.", "pri": "Should", "scope": "Core", "surface": "System", "status": "Designed", "trace": "email design reconcile item 2"}, {"id": "MSG-006", "req": "Quiet hours per tenant. Sends due in quiet hours wait for the window to open.", "why": "No clinic email at 2am.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Designed", "trace": "email design worker rules"}, {"id": "MSG-007", "req": "Delivery status tracked: sent, failed, bounced, clicked through signed links. No open-tracking pixel.", "why": "Apple Mail Privacy makes opens meaningless.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "Designed", "trace": "email design §4"}, {"id": "MSG-008", "req": "A hard bounce suppresses the address across all workflows.", "why": "Protects sender reputation.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Designed", "trace": ""}, {"id": "MSG-009", "req": "Transactional messages (confirmations, reminders, aftercare) are separated from marketing and not gated by marketing consent.", "why": "A patient who opted out of offers still gets their reminder.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Partial", "trace": "booking-engine notifications/"}, {"id": "MSG-010", "req": "Replies to platform messages are detected in the integration mailbox (matched by thread), attached to the person's timeline, pause that person's marketing workflows and alert staff.", "why": "The next email must not land while a question sits unanswered.", "pri": "Should", "scope": "Core", "surface": "Client console", "status": "Designed", "trace": "email design §5 phase 2"}, {"id": "MSG-011", "req": "WhatsApp aftercare with delivery and read status.", "why": "PureMed's patients read WhatsApp, not email.", "pri": "Should", "scope": "Pack:Aesthetics", "surface": "System", "status": "Designed", "trace": "technical-design.md §7.1; CARE rows"}, {"id": "MSG-012", "req": "If the sending provider fails repeatedly, the operator is alerted by a second path, and a health endpoint shows last success and queue depth.", "why": "A silent relay failure stops every workflow.", "pri": "Must", "scope": "Core", "surface": "Operator", "status": "Designed", "trace": "email design §4 watch-out"}, {"id": "MSG-013", "req": "Sending volume stays inside the integration mailbox's daily limit. The worker meters sends per day and holds anything over the limit to the next window rather than failing.", "why": "Every send now comes from one Workspace user, which has a daily cap. Check the current limit for Business Starter before Phase 0.", "pri": "Must", "scope": "Core", "surface": "System", "status": "New", "trace": ""}, {"id": "WFL-001", "req": "A workflow is a trigger, ordered steps and stop conditions, stored as versioned config with an ID.", "why": "The email sequence config, generalised.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Designed", "trace": "email design sequence definition"}, {"id": "WFL-002", "req": "Trigger types: tag added, form submitted, booking created/attended/cancelled/no-show, payment event, date reached (for example recall due), segment entered, manual enrol.", "why": "Covers every workflow in the pack library.", "pri": "Must", "scope": "Core", "surface": "System", "status": "New", "trace": ""}, {"id": "WFL-003", "req": "Step types are a closed set: wait, send message, add or remove tag, create staff task, branch on rule, notify staff, end. No arbitrary code steps.", "why": "A closed step set is what keeps workflows deterministic and supportable.", "pri": "Must", "scope": "Core", "surface": "System", "status": "New", "trace": ""}, {"id": "WFL-004", "req": "Stop conditions are checked before every step: booked, unsubscribed, bounced, replied, manual stop, entered a higher-priority workflow.", "why": "Stopping is a status change, not a clean-up job.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Designed", "trace": "email design worker rules"}, {"id": "WFL-005", "req": "Each pack ships a workflow library: lead magnet nurture, new enquiry follow-up, confirmation and reminders, pre-appointment forms, aftercare, review request, recall, no-show rebook, lapsed reactivation. The client enables and sets parameters; no free-form flow drawing in v1.", "why": "Parameterised templates are safer and cheaper to support than a canvas builder.", "pri": "Must", "scope": "Pack:Aesthetics", "surface": "Client console", "status": "New", "trace": ""}, {"id": "WFL-006", "req": "Manual actions: enrol a person or segment, pause, resume, skip a step, stop. Each records a reason.", "why": "The client must be able to intervene.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "WFL-007", "req": "Simulation before enabling: who would enter today, and the exact send schedule for a sample person.", "why": "Shows consequences before they happen.", "pri": "Should", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "WFL-008", "req": "Run view per workflow: people active, the step each is on, next action and when, and completed or stopped with reason.", "why": "Answers 'what is this automation doing right now?'", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "WFL-009", "req": "A person is in at most one marketing workflow at a time unless the workflow allows overlap. Priority order is set in config.", "why": "Prevents message pile-ups.", "pri": "Should", "scope": "Core", "surface": "System", "status": "New", "trace": ""}, {"id": "WFL-010", "req": "Changing a live workflow creates a new version. People already enrolled finish on their version unless explicitly migrated.", "why": "Editing mid-flight must not change what someone was promised.", "pri": "Must", "scope": "Core", "surface": "System", "status": "New", "trace": ""}, {"id": "WFL-011", "req": "Workflows can create staff tasks (call this lead, confirm this booking) that appear in the console inbox with a due time.", "why": "Some steps need a human.", "pri": "Should", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "WFL-012", "req": "A tenant-wide switch pauses all automated marketing sends.", "why": "For incidents, holidays and complaints.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "CMP-001", "req": "A campaign is one object: goal, audience segment, channels, content items (emails, posts, landing page), schedule and a success measure.", "why": "Links everything a push produces to its result.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "Partial", "trace": "Studio Campaign Builder (8 Jul)"}, {"id": "CMP-002", "req": "Audience preview shows the count and the exclusions (no consent, contacted recently, in an active workflow) before scheduling.", "why": "No surprises about who receives what.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "CMP-003", "req": "Frequency cap on marketing messages per person per 7 days, set per tenant.", "why": "Protects the list.", "pri": "Should", "scope": "Core", "surface": "System", "status": "New", "trace": ""}, {"id": "CMP-004", "req": "Every campaign item passes compliance lint and client approval before it can be scheduled. Approvals are logged.", "why": "Required for a regulated pack.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "Partial", "trace": "content/PLAN.md principle 3"}, {"id": "CMP-005", "req": "Campaign results: sent, clicked, leads captured, bookings attributed, revenue attributed, against the stated measure.", "why": "The client pays for bookings, not posts.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "CMP-006", "req": "Pack campaign templates: seasonal offer, treatment launch, lead magnet launch, reactivation.", "why": "Fast starts for self-serve tenants.", "pri": "Should", "scope": "Pack:Aesthetics", "surface": "Client console", "status": "New", "trace": ""}, {"id": "CMP-007", "req": "AI drafts campaign content from a brief against the tenant voice file. Drafts stay drafts until approved.", "why": "Where AI saves real time.", "pri": "Should", "scope": "Core", "surface": "Client console", "status": "Partial", "trace": "Campaign Builder LLM copy-draft"}, {"id": "CMP-008", "req": "Offer and discount codes linked to a campaign and redeemable at booking.", "why": "Closes the attribution loop for offers.", "pri": "Could", "scope": "Core", "surface": "System", "status": "New", "trace": "CRM-008"}, {"id": "SOC-001", "req": "Post lifecycle state machine: idea, drafted, review, approved, scheduled, published, measured, with flagged and rejected branches.", "why": "Built for PureMed Phase 1.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Built", "trace": "content/PLAN.md"}, {"id": "SOC-002", "req": "Monthly calendar generated from pillars and cadence config. The client approves the calendar.", "why": "Built.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "Built", "trace": "content/calendar/"}, {"id": "SOC-003", "req": "Asset library with tags, source (generated, uploaded, proxy) and marketing-photo consent status per image.", "why": "Shared client asset pool added on Stage 26 Sep.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "Partial", "trace": "image-library.json; Stage shared asset library"}, {"id": "SOC-004", "req": "One shared renderer, so what the client approves is exactly what publishes, brand overlay included.", "why": "Silent render defects were caught only by looking (Vera).", "pri": "Must", "scope": "Core", "surface": "System", "status": "Partial", "trace": "slide-templates.json"}, {"id": "SOC-005", "req": "Pack compliance lint blocks approval on a violation. No autoposting without human approval in a regulated pack.", "why": "Built for PureMed.", "pri": "Must", "scope": "Pack:Aesthetics", "surface": "System", "status": "Built", "trace": "content-lint.js; content/config/compliance.md"}, {"id": "SOC-006", "req": "Publish to Instagram and Facebook through the Meta Graph API and store platform post IDs.", "why": "Phase 2, blocked on Meta prerequisites.", "pri": "Must", "scope": "Core", "surface": "System", "status": "New", "trace": "fsc-ig-publishing-plan.md"}, {"id": "SOC-007", "req": "Several accounts per tenant (main plus satellites), each with its own calendar and link target.", "why": "Shuab's multi-account model.", "pri": "Should", "scope": "Pack:Aesthetics", "surface": "Client console", "status": "New", "trace": "growth plan GTM section"}, {"id": "SOC-008", "req": "Every post link carries UTM parameters so leads attribute to the post.", "why": "Feeds PPL-007.", "pri": "Must", "scope": "Core", "surface": "System", "status": "New", "trace": ""}, {"id": "SOC-009", "req": "Post metrics (reach, saves, profile visits, link clicks) pulled back and shown against the campaign.", "why": "Closes the social loop.", "pri": "Should", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "SOC-010", "req": "Client uploads photos and video from a phone into the asset library.", "why": "Nafisa's content starts on her phone.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "Partial", "trace": "Stage bulk upload (26 Sep)"}, {"id": "BKG-001", "req": "The booking engine is the core booking module: catalogue, availability as a pure function, rule-driven requirements, reschedule and cancel policy.", "why": "Phases 1-6 built and live-verified.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Built", "trace": "booking-engine-plan.md"}, {"id": "BKG-002", "req": "Every booking writes to the Person record and emits events workflows can trigger on.", "why": "Removes the need to parse booking emails.", "pri": "Must", "scope": "Core", "surface": "System", "status": "New", "trace": ""}, {"id": "BKG-003", "req": "Staff-made bookings pass the same requirement gates as online bookings.", "why": "Parity is a regulatory requirement.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "Designed", "trace": "BOOK-004"}, {"id": "BKG-004", "req": "Deep link to a specific service from any page, campaign or message.", "why": "Shortest path from interest to booking.", "pri": "Must", "scope": "Core", "surface": "Public", "status": "Built", "trace": "?svc= deep links"}, {"id": "BKG-005", "req": "Diary day and week views by resource, with quick actions: mark attended, no-show, cancel with reason.", "why": "Attendance is what recall and no-show workflows run on.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "Partial", "trace": "booking-engine admin UI"}, {"id": "BKG-006", "req": "Calendar sync where the engine owns truth and Google or Microsoft calendars are peers.", "why": "Built.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Built", "trace": "booking-engine-plan.md §7"}, {"id": "BKG-007", "req": "Attendance and no-shows are recorded as events.", "why": "Feeds recall, rebook and deposit rules.", "pri": "Must", "scope": "Core", "surface": "System", "status": "New", "trace": ""}, {"id": "BKG-008", "req": "Faces Consent is replaced, not integrated. After cutover the platform is the only system holding PureMed's customer records and bookings, and Faces is retired. No booking-email parsing, no sync, no dual running beyond the cutover window.", "why": "Decided 26 Sep 2026: one ecosystem for customer records and bookings.", "pri": "Must", "scope": "Tenant:PureMed", "surface": "System", "status": "Designed", "trace": "clinical plan §9 (full replacement); supersedes email design booking_emails"}, {"id": "BKG-009", "req": "Joint prescriber and practitioner availability, and routing by legal provider and location.", "why": "No vendor supports this; a reason to build.", "pri": "Must", "scope": "Pack:Aesthetics", "surface": "System", "status": "Designed", "trace": "BOOK-007; BOOK-008"}, {"id": "BKG-010", "req": "Waitlist with automatic offer when a slot frees.", "why": "Fills cancellations.", "pri": "Could", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "BKG-011", "req": "Cutover migrates booking history and the forward diary from Faces, reconciled appointment by appointment, so no future booking is lost or doubled.", "why": "Growth plan gap: no design existed for migrating diary state.", "pri": "Must", "scope": "Tenant:PureMed", "surface": "Operator", "status": "Designed", "trace": "clinical plan §6.6; growth plan open items"}, {"id": "BKG-012", "req": "At cutover the platform becomes the only writer to the diary calendar. Every other writer (the ChatGPT inbox automation, Faces' own sync) is switched off the same day.", "why": "Three writers to one calendar today; the day two disagree is a missed appointment.", "pri": "Must", "scope": "Tenant:PureMed", "surface": "System", "status": "Designed", "trace": "systems proposal item 1"}, {"id": "PAY-001", "req": "Deposit on every booking, staff-made included, by card, Apple Pay or Google Pay.", "why": "Answered: everyone pays, no exceptions.", "pri": "Must", "scope": "Core", "surface": "Public", "status": "Partial", "trace": "systems proposal item 5; PAY rows"}, {"id": "PAY-002", "req": "Payment events appear on the timeline. Provider state is mirrored, never authoritative on its own.", "why": "Built in the booking service.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Built", "trace": "booking-engine-plan.md §9"}, {"id": "PAY-003", "req": "Deposit policy is a rule table (for example two late cancellations means full prepayment).", "why": "Lets the system say no so the owner doesn't have to.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Designed", "trace": "systems proposal item 5"}, {"id": "PAY-004", "req": "Revenue per person and per acquisition source, derived for reporting.", "why": "Links spend to source.", "pri": "Should", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "PAY-005", "req": "Refunds record reason and actor.", "why": "Audit.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "Partial", "trace": ""}, {"id": "CLN-001", "req": "Customer and clinical record (S7) as a pack module keyed to the core Person. Reception sees a narrower, field-level view than practitioners, enforced below the app layer. Needed at Faces cutover, not after.", "why": "Faces holds the records today; bringing it in house needs S7 on day one. Full row set stays in the clinical register.", "pri": "Must", "scope": "Pack:Aesthetics", "surface": "Client console", "status": "Designed", "trace": "clinical register REC-001; S7"}, {"id": "CLN-002", "req": "Consent and medical questionnaire engine (S4), versioned, pre-filled on reissue. Carries the migrated Faces form library unchanged. Needed at Faces cutover.", "why": "Faces issues the consent forms today.", "pri": "Must", "scope": "Pack:Aesthetics", "surface": "Public", "status": "Designed", "trace": "CONS rows; S4"}, {"id": "CLN-003", "req": "Treatment notes with batch and lot traceability queryable across patients (S9).", "why": "Manufacturer recall.", "pri": "Must", "scope": "Pack:Aesthetics", "surface": "Client console", "status": "Designed", "trace": "NOTE rows; S9"}, {"id": "CLN-004", "req": "Digital toxin prescribing record with two signatures.", "why": "Replaces the paper pile.", "pri": "Must", "scope": "Pack:Aesthetics", "surface": "Client console", "status": "Designed", "trace": "systems proposal item 4"}, {"id": "CLN-005", "req": "Clinical photography: in-app capture, no camera roll, works offline, clinical and marketing consent split, gated export into the marketing asset library.", "why": "The only path from a clinical photo to a post.", "pri": "Must", "scope": "Pack:Aesthetics", "surface": "Client console", "status": "Designed", "trace": "PHOTO rows; S10; technical-design §6"}, {"id": "CLN-006", "req": "Treatment plans generated from the consultation, with acceptance state.", "why": "", "pri": "Should", "scope": "Pack:Aesthetics", "surface": "Client console", "status": "Designed", "trace": "S8; CRM-006"}, {"id": "CLN-007", "req": "A recorded complication or adverse event automatically suppresses marketing workflows (review requests, offers) for that person.", "why": "", "pri": "Must", "scope": "Pack:Aesthetics", "surface": "System", "status": "Designed", "trace": "CRM-007"}, {"id": "CLN-008", "req": "Recall interval per treatment drives the next-due date that recall workflows trigger on.", "why": "", "pri": "Must", "scope": "Pack:Aesthetics", "surface": "System", "status": "Designed", "trace": "CRM-004"}, {"id": "RPT-001", "req": "Home dashboard: new leads, bookings, bookings from leads, diary fill for the next 14 days, messages sent, items waiting for the client.", "why": "The owner's weekly pulse on one screen.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "RPT-002", "req": "Funnel from visit to capture to booking to attendance, by source and campaign, derived from events.", "why": "", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "RPT-003", "req": "Attribution rules are stated and fixed: first touch and last touch shown side by side, no modelled attribution.", "why": "A number the client can check by hand.", "pri": "Must", "scope": "Core", "surface": "System", "status": "New", "trace": ""}, {"id": "RPT-004", "req": "Every figure on a dashboard opens the list of records behind it.", "why": "No unexplained numbers. Same discipline as the figures gate.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": "SOP-OPS-008"}, {"id": "RPT-005", "req": "Diary fill rate has one agreed definition per tenant (bookable minutes booked divided by bookable minutes offered).", "why": "Growth plan: no agreed measure of 'drive bookings'.", "pri": "Must", "scope": "Core", "surface": "System", "status": "New", "trace": "growth plan open items"}, {"id": "RPT-006", "req": "A monthly client report is generated from the same queries as the dashboard.", "why": "No hand-built reports.", "pri": "Should", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "RPT-007", "req": "Workflow performance: entered, completed, stopped by reason, booked within N days.", "why": "Shows which automations earn their place.", "pri": "Should", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "UXC-001", "req": "One sign-in console with: Today, People, Diary, Campaigns, Workflows, Content (site, blog, social), Inbox, Reports, Settings.", "why": "Replaces Stage + Studio + ntfy + inbox-checking as separate places.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "UXC-002", "req": "The console opens on a 'Needs you' inbox: approvals, tasks, unmatched bookings, replies, failed sends, ordered by due time.", "why": "The owner has minutes, not hours.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "UXC-003", "req": "Activity feed of what the system did, newest first, each row with a plain-language reason and a link to the workflow or rule.", "why": "Answers 'what was the last action?'", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "UXC-004", "req": "Person page header: stage, last booked, next booking, source, consents. Below it the timeline. Actions: book, enrol in workflow, tag, message, export, erase.", "why": "", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "UXC-005", "req": "Mobile-first for the owner-operator: Today, Inbox, person lookup, approve content and upload photos work one-handed on a phone.", "why": "Nafisa runs the business from her phone.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": "systems proposal 'What I heard'"}, {"id": "UXC-006", "req": "Plain language throughout: people not contacts, messages not sends, 'why this happened' not rule trace.", "why": "", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "UXC-007", "req": "Roles: Owner, Practitioner, Reception, Marketing, Operator (MSS). Each sees only its modules and fields.", "why": "Shuab needs campaigns, not clinical notes.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "UXC-008", "req": "Every outward or destructive action states its consequence before confirming ('Send to 212 people now').", "why": "", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "UXC-009", "req": "Global search across people, bookings and content.", "why": "", "pri": "Should", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "UXC-010", "req": "Phone notifications for events the tenant chooses (new lead, booking, reply, failed payment).", "why": "", "pri": "Should", "scope": "Core", "surface": "Client console", "status": "Partial", "trace": "ntfy"}, {"id": "UXC-011", "req": "Empty and error states say what to do next.", "why": "", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "UXC-012", "req": "The console meets WCAG 2.2 AA.", "why": "", "pri": "Should", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "OPS-001", "req": "Operator console: tenants, enabled modules, health, pending approvals, latest gate results.", "why": "The status board, per tenant.", "pri": "Should", "scope": "Core", "surface": "Operator", "status": "Partial", "trace": "workspace-status.js"}, {"id": "OPS-002", "req": "Support access 'view as tenant user' is logged and visible to the tenant.", "why": "", "pri": "Should", "scope": "Core", "surface": "Operator", "status": "New", "trace": ""}, {"id": "OPS-003", "req": "A new vertical pack is created from a pack template and must pass the gates before a tenant can use it.", "why": "How the second niche gets built.", "pri": "Must", "scope": "Core", "surface": "Operator", "status": "New", "trace": ""}, {"id": "OPS-004", "req": "Platform releases run the determinism, data-protection, figures and design gates. Tenants run a pinned platform version with staged rollout.", "why": "", "pri": "Must", "scope": "Core", "surface": "Operator", "status": "Partial", "trace": "SOP-OPS-005/006/008"}, {"id": "OPS-005", "req": "Every module ships an operator SOP.", "why": "Standing SOP rule.", "pri": "Must", "scope": "Core", "surface": "Operator", "status": "Partial", "trace": "sops/ template"}, {"id": "OPS-006", "req": "A config change on one tenant cannot affect another. Changes to shared templates or renderers require a regression check across all tenants.", "why": "", "pri": "Must", "scope": "Core", "surface": "Operator", "status": "New", "trace": "Vera shared-renderer note"}, {"id": "AIA-001", "req": "AI drafts copy (messages, posts, blog, campaigns) from a brief, the tenant voice file and pack compliance. Output always enters as a draft.", "why": "", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "Partial", "trace": "copywriting skill; Campaign Builder"}, {"id": "AIA-002", "req": "AI output passes the same deterministic lint as human copy. AI is never the linter.", "why": "", "pri": "Must", "scope": "Core", "surface": "System", "status": "Partial", "trace": "content-lint.js"}, {"id": "AIA-003", "req": "AI suggestions show their provenance: model, prompt template version, date.", "why": "LLM-transparency rule.", "pri": "Should", "scope": "Core", "surface": "Client console", "status": "New", "trace": "studio-workflow-alignment-spec.md"}, {"id": "AIA-004", "req": "Reply classification can pause a workflow and alert staff. It never sends a reply.", "why": "", "pri": "Could", "scope": "Core", "surface": "System", "status": "Designed", "trace": "email design §5"}, {"id": "AIA-005", "req": "No clinical data goes to an AI provider without a DPIA-approved basis. Clinical AI features are off by default.", "why": "", "pri": "Must", "scope": "Pack:Aesthetics", "surface": "System", "status": "New", "trace": ""}, {"id": "AIA-006", "req": "AI usage and cost metered per tenant.", "why": "Needed to price plans.", "pri": "Could", "scope": "Core", "surface": "Operator", "status": "New", "trace": ""}, {"id": "INT-001", "req": "Each tenant connects one business mailbox (Google Workspace or Microsoft 365) as its single email integration point. All outbound mail sends from it, replies and bounces are read from it, staff notifications go to it, and calendar sync uses its calendar. No third-party email service and no separate sending addresses.", "why": "One mailbox the business already owns and watches. Replies and history stay where the team works.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Designed", "trace": "email design §3-4"}, {"id": "INT-002", "req": "Meta Graph API for publishing and insights.", "why": "", "pri": "Must", "scope": "Core", "surface": "System", "status": "New", "trace": "fsc-ig-publishing-plan.md"}, {"id": "INT-003", "req": "WhatsApp Business Platform.", "why": "", "pri": "Should", "scope": "Core", "surface": "System", "status": "Designed", "trace": "technical-design.md §7.1"}, {"id": "INT-004", "req": "Stripe per tenant, with the tenant as merchant of record.", "why": "", "pri": "Must", "scope": "Core", "surface": "System", "status": "Partial", "trace": "booking-engine payments/"}, {"id": "INT-005", "req": "Google and Microsoft calendars, connected through the integration mailbox's account. For PureMed, confirm the diary Nafisa watches is care@'s calendar before cutover.", "why": "", "pri": "Must", "scope": "Core", "surface": "System", "status": "Built", "trace": "booking-engine calendar/"}, {"id": "INT-006", "req": "Faces Consent migration into the platform: 475 patient records, the consent form library as-is, signed consent PDFs, booking history, plus Acuity notes for long-standing patients. Dry run and reconciliation report before cutover.", "why": "Bringing Faces in house makes this the critical path.", "pri": "Must", "scope": "Tenant:PureMed", "surface": "Operator", "status": "Designed", "trace": "MIG rows; clinical plan §6"}, {"id": "INT-007", "req": "Settings lists every connection with status, last sync and a reconnect action.", "why": "Expired tokens are the most common silent failure.", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": ""}, {"id": "INT-008", "req": "Outbound webhooks and scheduled exports for tenants who keep another tool.", "why": "", "pri": "Could", "scope": "Core", "surface": "System", "status": "New", "trace": ""}, {"id": "INT-009", "req": "PureMed's integration mailbox is care@puremed.uk (the only user on Workspace Business Starter, and the admin account). Every platform email integration connects to care@ directly.", "why": "Decided 26 Sep 2026.", "pri": "Must", "scope": "Tenant:PureMed", "surface": "System", "status": "Designed", "trace": "puremed-email-handover.md; email design reconcile item 2"}, {"id": "INT-010", "req": "Faces exit: a full export (patients, consent library, signed forms, booking history, forward diary) is verified complete against Faces before contract notice is given.", "why": "Once notice is given there is no second chance at the data.", "pri": "Must", "scope": "Tenant:PureMed", "surface": "Operator", "status": "New", "trace": "clinical plan §6; decisions log 'Faces Consent admin'"}, {"id": "SEC-001", "req": "Staff sign-in with 2FA and session timeout. No shared logins.", "why": "", "pri": "Must", "scope": "Core", "surface": "Client console", "status": "New", "trace": "SEC rows"}, {"id": "SEC-002", "req": "Identifiers are never credentials. A tenant UUID emailed to clients cannot grant access.", "why": "Data protection review finding.", "pri": "Must", "scope": "Core", "surface": "System", "status": "New", "trace": "data-protection-review-2026-08-18"}, {"id": "SEC-003", "req": "Encryption in transit and at rest. Clinical files in encrypted object storage.", "why": "", "pri": "Must", "scope": "Core", "surface": "System", "status": "Designed", "trace": "technical-design.md §8"}, {"id": "SEC-004", "req": "Access to personal and clinical data is logged (who viewed what, when).", "why": "", "pri": "Must", "scope": "Core", "surface": "System", "status": "New", "trace": ""}, {"id": "SEC-005", "req": "Daily backups with a quarterly tested restore. Proposed RPO 24 hours, RTO 8 hours.", "why": "", "pri": "Must", "scope": "Core", "surface": "Operator", "status": "New", "trace": ""}, {"id": "SEC-006", "req": "Monitoring and alerts: uptime, job queue depth, failed sends, payment webhook failures.", "why": "", "pri": "Must", "scope": "Core", "surface": "Operator", "status": "Partial", "trace": ""}, {"id": "SEC-007", "req": "Production runs on a managed UK host. The Pi holds nothing but non-personal review content.", "why": "", "pri": "Must", "scope": "Core", "surface": "System", "status": "Designed", "trace": "booking-engine-plan.md §11"}, {"id": "SEC-008", "req": "Breach register and incident procedure per tenant.", "why": "", "pri": "Must", "scope": "Core", "surface": "Operator", "status": "New", "trace": ""}, {"id": "SEC-009", "req": "The mailbox connection uses the narrowest scopes that work (send, read, calendar). The token is held server-side only, and the code reads only threads the platform started plus delivery failures. Every mailbox read is logged, and the token can be revoked from the Workspace admin console.", "why": "care@ holds all patient correspondence. Google can't limit a token to a label, so the limit is enforced in code and must be audited.", "pri": "Must", "scope": "Core", "surface": "System", "status": "Designed", "trace": "email design §3 access to care@"}, {"id": "CMPL-001", "req": "Each pack has a human-written compliance rules file, never generated (aesthetics: no prescription-only medicine advertising, before-and-after restrictions, no appeal to under-18s).", "why": "", "pri": "Must", "scope": "Pack:Aesthetics", "surface": "Operator", "status": "Built", "trace": "content/config/compliance.md"}, {"id": "CMPL-002", "req": "Compliance rules are executable (word lists, patterns) and run on every surface: site, messages, social, campaigns.", "why": "", "pri": "Must", "scope": "Pack:Aesthetics", "surface": "System", "status": "Partial", "trace": "content-lint.js"}, {"id": "CMPL-003", "req": "Patient-facing clinical claims need clinician approval, recorded against the content version.", "why": "", "pri": "Must", "scope": "Pack:Aesthetics", "surface": "Client console", "status": "Designed", "trace": "email design §5"}, {"id": "CMPL-004", "req": "Treatments delivered under another provider's CQC registration carry that provider and location.", "why": "", "pri": "Must", "scope": "Tenant:PureMed", "surface": "System", "status": "Designed", "trace": "clinical plan §3.1"}, {"id": "COM-001", "req": "Plans sold by module: Presence (site, content, social), Growth (+ capture, messaging, workflows, campaigns), Practice (+ booking, payments), Clinical (+ clinical pack).", "why": "", "pri": "Should", "scope": "Core", "surface": "Operator", "status": "New", "trace": ""}, {"id": "COM-002", "req": "The same console serves managed tenants (MSS runs content and campaigns) and self-serve tenants.", "why": "Managed first; self-serve is a later layer.", "pri": "Must", "scope": "Core", "surface": "Operator", "status": "New", "trace": ""}, {"id": "COM-003", "req": "Contract clause on scope of responsibility: MSS operates the software; clinical, regulatory and advertising decisions stay with the tenant.", "why": "Flagged as a prerequisite for the Systems line.", "pri": "Must", "scope": "Core", "surface": "Operator", "status": "New", "trace": "mss-decisions-log Systems service line"}, {"id": "COM-004", "req": "Tenant subscription billing.", "why": "", "pri": "Could", "scope": "Core", "surface": "Operator", "status": "New", "trace": ""}, {"id": "COM-005", "req": "Transferability is claimed only after one non-aesthetics tenant is onboarded with zero core code change.", "why": "The test that makes 'deterministic and transferable' true.", "pri": "Must", "scope": "Core", "surface": "Operator", "status": "New", "trace": ""}]};
